performance.beforeInteractionManager:
// ❌ Before in <{{comp}} /> (runs heavy computation while transition animates):
useEffect(() => {
  loadHeavyData();
}, []);

performance.afterInteractionManager:
// ✅ After (waits until transition completes smoothly):
useEffect(() => {
  const task = InteractionManager.runAfterInteractions(() => {
    loadHeavyData();
  });
  return () => task.cancel();
}, []);

performance.beforeFlatListWindowing:
// FlatList Windowing Optimization for <{{comp}} />:
<FlatList
  data={items}
  maxToRenderPerBatch={10}
  windowSize={5}
  initialNumToRender={8}
  removeClippedSubviews={true}
/>

performance.beforeImageCaching:
// Image Optimization for <{{comp}} />:
<Image
  source={{ uri: imageUrl, cache: 'force-cache' }}
  resizeMode="cover"
  fadeDuration={100}
/>

performance.afterInlineStyles:
// ✅ After (hoisted StyleSheet reference):
const styles = StyleSheet.create({ container: { flex: 1, padding: 16, backgroundColor: '#ffffff' } });
<View style={styles.container} />
